<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessageBox,ElMessage} from 'element-plus'
import {api,fmt} from '../api'
import {useWorkspace} from '../store'
import Status from '../components/Status.vue'
import Icon from '../components/Icon.vue'
import FailureTriage from '../components/FailureTriage.vue'
import Attachments from '../components/Attachments.vue'
const store=useWorkspace(),route=useRoute(),router=useRouter(),items=ref<any[]>([]),total=ref(0),page=ref(1),search=ref(''),status=ref(''),loading=ref(false),run=ref<any>(null),tab=ref('results'),resultFilter=ref(''),error=ref(false)
const id=computed(()=>route.params.id),active=computed(()=>['queued','running'].includes(run.value?.status)),results=computed(()=>run.value?.results.filter((r:any)=>!resultFilter.value||r.status===resultFilter.value)||[])
let version=0
async function load(quiet=false){if(!store.projectId)return;const v=++version;if(!quiet)loading.value=true;try{if(id.value){const {data}=await api.get(`runs/${id.value}/`);if(v===version){run.value=data;error.value=false}}else{if(store.canEdit){const pending=await api.get('jobs/',{params:{project:store.projectId,status:'completed',page:1}});const missing=(pending.data.results||[]).filter((j:any)=>['api','ui'].includes(j.kind));await Promise.all(missing.map((j:any)=>api.post(`jobs/${j.id}/generate_report/`).catch(()=>null)))}const {data}=await api.get('runs/',{params:{project:store.projectId,page:page.value,search:search.value,status:status.value}});if(v===version){items.value=data.results;total.value=data.count;error.value=false}}}catch{error.value=true}finally{if(v===version)loading.value=false}}
function filter(){page.value=1;load()}
watch(()=>id.value,()=>{run.value=null;tab.value='results';load()},{immediate:true})
watch(()=>store.projectId,()=>{if(id.value)router.push('/runs');else filter()})
const timer=setInterval(()=>{if(active.value||(!id.value&&items.value.some(r=>['running','queued'].includes(r.status))))load(true)},2000);onUnmounted(()=>clearInterval(timer))
async function cancel(){await api.post(`runs/${run.value.id}/cancel/`);load()}
async function remove(item:any){try{await ElMessageBox.confirm('确认永久删除此报告与关联附件？','删除报告',{type:'warning'})}catch{return}await api.delete(`runs/${item.id}/`);ElMessage.success('报告已删除');if(id.value)router.push('/runs');else{if(items.value.length===1&&page.value>1)page.value--;load()}}
</script>
<template><div v-loading="loading"><template v-if="!id"><div class="page-heading"><div><div class="heading-eyebrow">EXECUTION & INSIGHTS</div><h1>{{ $t('测试报告') }}<span class="heading-tag">{{total}}</span></h1><p>{{ $t('追踪每一次执行，查看测试结果、步骤日志与历史记录。') }}</p></div><el-button @click="load()"><Icon name="Refresh" :size="16"/>{{ $t('刷新报告') }}</el-button></div><div class="simulation-banner"><Icon name="InfoFilled" :size="18"/><div><strong>测试报告</strong><span>测试资产、接口自动化和 UI 自动化任务完成后会在此生成报告；执行模式与结果来源会在报告中标明。</span></div></div><section class="panel"><div class="list-toolbar"><h3>{{ $t('执行记录') }}</h3><div class="inline-actions"><el-input v-model="search" :placeholder="$t('搜索任务名称')" style="width:220px" clearable @keyup.enter="filter" @clear="filter"/><el-select v-model="status" :placeholder="$t('全部状态')" clearable style="width:135px" @change="filter"><el-option v-for="(label,value) in {queued:'排队中',running:'执行中',completed:'已完成',failed:'失败',cancelled:'已取消'}" :key="value" :value="value" :label="label"/></el-select><el-button @click="filter">{{ $t('查询') }}</el-button></div></div><el-table :data="items"><el-table-column :label="$t('测试任务')" min-width="240"><template #default="{row}"><div class="table-title"><span class="table-icon"><Icon name="DataAnalysis" :size="18"/></span><div><el-button link class="asset-name" @click="router.push('/runs/'+row.id)">{{row.name}}</el-button><small>RUN-{{String(row.id).padStart(4,'0')}} · {{row.mode==='live'?'真实执行':'模拟模式'}}</small></div></div></template></el-table-column><el-table-column :label="$t('执行状态')" width="120"><template #default="{row}"><Status :value="row.status"/></template></el-table-column><el-table-column :label="$t('进度')" width="155"><template #default="{row}"><el-progress :percentage="row.progress" :stroke-width="5"/></template></el-table-column><el-table-column :label="$t('通过 / 失败')" width="120"><template #default="{row}"><b class="text-green">{{row.metrics.passed??'—'}}</b> / <b class="text-red">{{row.metrics.failed??'—'}}</b></template></el-table-column><el-table-column :label="$t('创建时间')" width="145"><template #default="{row}">{{fmt(row.created_at)}}</template></el-table-column><el-table-column :label="$t('操作')" width="125"><template #default="{row}"><el-button link type="primary" @click="router.push('/runs/'+row.id)">{{ $t('详情') }}</el-button><el-button v-if="store.canEdit&&!['queued','running'].includes(row.status)" link type="danger" @click="remove(row)">{{ $t('删除') }}</el-button></template></el-table-column><template #empty><el-empty :description="$t('还没有报告，从就绪的用例、计划或流程发起模拟执行')"/></template></el-table><div class="pagination"><span>共 {{total}} 次执行</span><el-pagination v-model:current-page="page" :total="total" layout="prev, pager, next" @current-change="load"/></div></section></template>
<template v-else-if="run"><el-button link class="back-button" @click="router.push('/runs')"><Icon name="ArrowLeft" :size="14"/>{{ $t('返回测试报告') }}</el-button><div class="page-heading"><div><div class="heading-eyebrow">RUN-{{String(run.id).padStart(4,'0')}}</div><h1>{{run.name}}</h1><p>{{run.created_by_name}} 发起于 {{fmt(run.created_at)}} <span class="mode-pill">{{run.mode==='live'?'真实执行':'模拟模式'}}</span></p></div><div class="inline-actions"><el-button v-if="active&&store.canEdit" @click="cancel">{{ $t('取消执行') }}</el-button><a :href="`/api/runs/${run.id}/export/`" class="button-link"><Icon name="Download" :size="16"/>{{ $t('导出 JSON 报告') }}</a><el-button @click="load()"><Icon name="Refresh"/></el-button></div></div><div v-if="run.mode!=='live'" class="simulation-banner"><Icon name="WarningFilled"/><div><strong>模拟执行报告</strong><span>结果由模拟执行器生成，不代表真实网络请求或设备操作。</span></div></div><div v-else class="simulation-banner"><Icon name="SuccessFilled"/><div><strong>真实执行报告</strong><span>报告记录来自 {{run.execution_context.executor||'已配置的执行器'}}，包含执行结果与后台保存的附件。</span></div></div><section class="panel run-summary"><p class="helper">执行器：{{run.execution_context.executor||'内置模拟执行器'}}<span v-if="run.execution_context.agent"> · Agent：{{run.execution_context.agent.name}} · {{run.execution_context.resources?.length||0}} 项关联能力（配置快照）</span></p><div><Status :value="run.status"/><span class="muted">{{active?'页面每 2 秒自动更新':'报告已保存在本地数据库'}}</span></div><el-progress :percentage="run.progress" :stroke-width="8"/><p v-if="run.status==='queued'" class="helper">{{ $t('等待后台 Worker 领取任务。若持续排队，请确认 runworker 服务已启动。') }}</p><div class="report-metrics"><div v-for="(label,key) in {total:'用例总数',passed:'通过',failed:'失败',skipped:'跳过'}" :key="key"><strong :class="key==='passed'?'text-green':key==='failed'?'text-red':''">{{run.metrics[key]??'—'}}</strong><span>{{label}}</span></div><div><strong>{{run.metrics.pass_rate??'—'}}<small>%</small></strong><span>{{ $t('通过率') }}</span></div><div><strong>{{run.metrics.duration_ms!=null?(run.metrics.duration_ms/1000).toFixed(2):'—'}}<small>s</small></strong><span>{{ $t('执行耗时') }}</span></div></div></section>
<FailureTriage :data="run.execution_context?.triage"/><section class="panel report-panel"><el-tabs v-model="tab"><el-tab-pane :label="$t('用例结果')" name="results"><div class="result-toolbar"><h3>{{ $t('执行详情') }}<span class="count-badge">{{run.results.length}}</span></h3><el-select v-model="resultFilter" :placeholder="$t('全部结果')" clearable style="width:140px"><el-option :label="$t('通过')" value="passed"/><el-option :label="$t('失败')" value="failed"/><el-option :label="$t('跳过')" value="skipped"/></el-select></div><el-collapse><el-collapse-item v-for="r in results" :key="r.case_id" :name="r.case_id"><template #title><div class="result-title"><Status :value="r.status"/><b>{{r.name}}</b><span class="muted">{{r.steps.length}} 个步骤 · {{r.duration_ms}} ms</span></div></template><el-table :data="r.steps"><el-table-column label="#" width="45"><template #default="{row}">{{row.index+1}}</template></el-table-column><el-table-column prop="action" :label="$t('操作步骤')"/><el-table-column prop="expected" :label="$t('预期结果')"/><el-table-column prop="actual" :label="$t('模拟结果')"/><el-table-column :label="$t('状态')" width="95"><template #default="{row}"><Status :value="row.status"/></template></el-table-column></el-table><el-button v-if="r.status==='failed'&&run.mode==='live'&&run.execution_context.source_job_id&&['api','ui'].includes(run.execution_context.source_kind)" type="primary" plain @click="router.push({path:'/ai',query:{operation:'analyze',job:run.execution_context.source_job_id,case_id:r.case_id,target:run.execution_context.source_kind}})">分析并修复用例</el-button></el-collapse-item></el-collapse><el-empty v-if="!results.length" :description="$t('暂无符合条件的用例结果')" :image-size="65"/></el-tab-pane><el-tab-pane :label="$t('执行日志')" name="logs"><div class="log-console"><div v-for="(l,i) in run.logs" :key="i"><time>{{fmt(l.at)}}</time><b :class="l.level">{{l.level}}</b><span>{{l.message}}</span></div><p v-if="!run.logs.length">{{ $t('等待执行器产生日志…') }}</p></div></el-tab-pane><el-tab-pane :label="$t('执行历史')" name="history"><el-timeline><el-timeline-item v-for="(h,i) in run.history" :key="i" :timestamp="fmt(h.at)" color="#7376e7"><strong>{{h.message}}</strong><p><Status :value="h.status"/></p></el-timeline-item></el-timeline></el-tab-pane><el-tab-pane :label="$t('截图与附件')" name="files"><Attachments :run="run.id" :results="run.results"/></el-tab-pane></el-tabs></section></template><el-empty v-else-if="error" :description="$t('报告不存在或当前账号无权访问')"><el-button @click="router.push('/runs')">{{ $t('返回报告列表') }}</el-button></el-empty></div></template>
